;; curriculum: Calc-1 (gr 12 / undergrad) — derivative as slope of tangent; prerequisites: valley, ramp
;; math target: the ramp you skate is the valley's derivative; its height at any x is the slope dy/dx of the valley.

app riya-level-deriv "1.1.0"
"riya level 19 · Derivative — the ramp under your feet is the valley's slope: low where the valley is flat, high where it is steep. Skate the derivative — catch 5 ★! Composed from std-platformer-body + std-objective-flow + std-fx-particles + std-pickup + std-tutorial-overlay, rendered through math-canvas so the axes and the world's own function stay visible. Rebound into the riya-game-platformer organism (menu + all eighteen worlds)."

;; @exposure internal

orbital RiyaDerivOrbital {
  uses Body from "std/behaviors/std-platformer-body"
  uses Gate from "std/behaviors/std-objective-flow"
  uses Particles from "std/behaviors/std-fx-particles"
  uses Pickup from "std/behaviors/std-pickup"
  uses Tutorial from "std/behaviors/std-tutorial-overlay"
  uses Genre from "std/behaviors/std-platformer-puzzle"

  type RiyaDerivBody = {
    x : number!
    y : number!
    width : number!
    height : number!
    vx : number
    vy : number
    grounded : boolean
    facingRight : boolean
  }
  type RiyaDerivPlatform = {
    id : string
    x : number!
    y : number!
    width : number!
    height : number!
    type : "ground" | "platform" | "hazard" | "goal"
  }
  type RiyaDerivFx = {
    id : string!
    type : string!
    x : number!
    z : number
    y : number
    message : string
    ttl : number!
    maxTtl : number
    bornAt : number
    space : string
    effect : string
    color : string
    size : number
    vx : number
    vy : number
    vz : number
    particleCount : number
    animation : string
  }
  type RiyaDerivPickup = {
    id : string!
    x : number!
    y : number!
    kind : string!
    glyph : string
    message : string
    collected : boolean
  }
  type RiyaDerivCurveSample = {
    x : number!
    y : number!
  }
  type RiyaDerivCurve = {
    label : string
    color : string
    samples : [RiyaDerivCurveSample]!
    dash : "dashed" | "dotted"
  }
  type RiyaDerivGuide = {
    kind : "vline" | "hline"!
    at : number!
    color : string
    dash : "dashed" | "dotted"
    label : string
  }
  type RiyaDerivFxPreset = {
    type : string!
    color : string
    color2 : string
    size : number
    shape : string
    count : number
    glow : number
    vy : number
    animation : string
  }

  entity RiyaDerivState [runtime, shared] {
    id : string!
    active : boolean = false
    body : RiyaDerivBody = { x: -9, y: 4, width: 0.6, height: 0.6, vx: 0, vy: 0, grounded: false, facingRight: true }
    fell : boolean = false
    hazardId : string = ""
    goalId : string = ""
    skating : boolean = false
    pickups : [RiyaDerivPickup] = []
    pickupCompleted : boolean = false
    total : number = 0
    score : number = 0
    objectivesLeft : number = 0
    result : string = "none"
    fx : [RiyaDerivFx] = []
    celebrated : boolean = false
    seq : number = 0
    lastText : string = ""
    zoneId : string = "deriv"
    platforms : [RiyaDerivPlatform] = []
    curves : [RiyaDerivCurve] = []
    guides : [RiyaDerivGuide] = []
    traceSamples : [RiyaDerivCurveSample] = []
  }

  entity DerivTutorialData [runtime] {
    id : string!
    step : number = 0
    done : boolean = false
  }

  trait DerivBody = Body.traits.PlatformerBody -> RiyaDerivState {
    events {
      STEER: DERIV_STEER
      JUMP: DERIV_LEAP
      PLACE: DERIV_PLACE
      RESTART: DERIV_RESTART
      BODY_MOVED: DERIV_MOVED
      BODY_JUMPED: DERIV_JUMPED
      BODY_LANDED: DERIV_LANDED
      BODY_HAZARD: DERIV_HAZARD
      BODY_GOAL: DERIV_GOAL
      BODY_FELL: DERIV_FELL
      BODY_SKATE_START: DERIV_SKATE_ON
      BODY_SKATE_END: DERIV_SKATE_OFF
      SET_PLATFORMS: DERIV_SET_PLATFORMS
      SET_SKATE_CURVE: DERIV_SET_SKATE_CURVE
    }
    config {
      running: true
      spawn: { x: -9, y: 4, width: 0.6, height: 0.6, vx: 0, vy: 0, grounded: false, facingRight: true }
      gravity: -24
      jumpStrength: 11
      moveSpeed: 5
      maxFallSpeed: 14
      xMin: -10
      xMax: 9.4
      killY: -3
      skate: true
      skateSnap: 0.9
    }
  }

  trait DerivGate = Gate.traits.ObjectiveFlow -> RiyaDerivState {
    events {
      PROGRESS: DERIV_PROGRESS
      GAME_END: DERIV_GAME_END
      RESTART: DERIV_RESTART
    }
    config { running: true }
  }

  trait DerivFx = Particles.traits.FxParticles -> RiyaDerivState {
    events {
      BURST: DERIV_BURST
    }
    config { running: true }
  }

  trait DerivTutorialPreview -> DerivTutorialData [interaction, instance] {
    initial: idle
    state idle {
      INIT -> idle
        (render-ui center null)
    }
  }

  trait DerivTutorial = Tutorial.traits.TutorialOverlay -> DerivTutorialData {
    events {
      SHOW: DERIV_TUTORIAL_SHOW
      TUTORIAL_DONE: DERIV_TUTORIAL_DONE
    }
    config {
      autoShow: true
      previewTrait: @trait.DerivTutorialPreview
      steps: [
        { id: "intro", title: "Derivative", body: "The solid ramp is the slope of world 3's valley. The dashed ghost is the valley itself. Where the valley is flat, the ramp is near zero." }
      ]
    }
  }

  trait DerivPickup = Pickup.traits.Pickup -> RiyaDerivState {
    events {
      PICKED: DERIV_PICKED
      COLLECT: DERIV_COLLECT
      PICKUP_SET_COMPLETED: DERIV_PICKUP_SET_COMPLETED
      SET_FEATURES: DERIV_SET_FEATURES
    }
    config {
      running: true
      reachX: 0.7
      reachY: 1.2
    }
  }

  trait DerivLevelData -> @rebindable RiyaDerivState [lifecycle] {
    initial: active

    state active {
      INIT -> active
        (emit RIYA_LEVEL_DATA {
          id: "deriv"
          name: @config.worldName
          equation: @config.equation
          concept: @config.concept
          regionColor: @config.regionColor
          entryY: @config.entryY
          exitY: @config.exitY
          platforms: (array/map @config.platforms (fn p @p))
          stars: (array/map @config.stars (fn s @s))
          skateCurve: (array/map @config.skateCurve (fn c @c))
          curveOverlay: (array/map @config.curveOverlay (fn c @c))
          guides: (array/map @config.guides (fn g @g))
          traceSamples: (array/map @config.traceSamples (fn t @t))
        })
    }

    emits {
      RIYA_LEVEL_DATA -> external {
        id : string!
        name : string!
        equation : string!
        concept : string!
        regionColor : string!
        entryY : number!
        exitY : number!
        platforms : [RiyaDerivPlatform]!
        stars : [RiyaDerivPickup]!
        skateCurve : [RiyaDerivCurveSample]
        curveOverlay : [RiyaDerivCurve]
        guides : [RiyaDerivGuide]
        traceSamples : [RiyaDerivCurveSample]
      }
        @description "The zone's canonical static geometry + pedagogy, broadcast once on INIT in zone-local coordinates. This atom's own play trait consumes it to seed the body/pickup authorities and the render; the riya open-world organism consumes the same event and applies its zone offset, so standalone and composed can never diverge."
        @tier "domain"
    }

    config {
      worldName : string = "Derivative"
        @label "World Name"
        @description "This world's display name — the open world's zone banner reads it from RIYA_LEVEL_DATA."
        @tier "presentation"
      equation : string = "y = x/8 + 4"
        @label "Equation"
        @description "The zone's skate/banner equation."
        @tier "presentation"
      concept : string = "this ramp IS the valley's slope: far from the dashed line on the steep walls, crossing it where the valley bottoms out"
        @label "Concept"
        @description "The world's one math idea."
        @tier "presentation"
      regionColor : string = "#38bdf8"
        @label "Region Color"
        @description "Zone band accent in the open world."
        @tier "presentation"
      entryY : number = 2.9
        @label "Entry Y"
        @description "Run-surface height at the zone's left edge (top of ground tile b0); the open world stitches its incoming bridge to this."
        @tier "domain"
      exitY : number = 5.1
        @label "Exit Y"
        @description "Run-surface height at the zone's right edge (top of ground tile b11); the open world stitches its outgoing bridge to this."
        @tier "domain"
      platforms : [RiyaDerivPlatform] = [
        { id: "b0", x: -9.6, y: -2, width: 1.6, height: 4.9, type: "ground" }
        { id: "b1", x: -8, y: -2, width: 1.6, height: 5.1, type: "ground" }
        { id: "b2", x: -6.4, y: -2, width: 1.6, height: 5.3, type: "ground" }
        { id: "b3", x: -4.8, y: -2, width: 1.6, height: 5.5, type: "ground" }
        { id: "b4", x: -3.2, y: -2, width: 1.6, height: 5.7, type: "ground" }
        { id: "b5", x: -1.6, y: -2, width: 1.6, height: 5.9, type: "ground" }
        { id: "b6", x: 0, y: -2, width: 1.6, height: 6.1, type: "ground" }
        { id: "b7", x: 1.6, y: -2, width: 1.6, height: 6.3, type: "ground" }
        { id: "b8", x: 3.2, y: -2, width: 1.6, height: 6.5, type: "ground" }
        { id: "b9", x: 4.8, y: -2, width: 1.6, height: 6.7, type: "ground" }
        { id: "b10", x: 6.4, y: -2, width: 1.6, height: 6.9, type: "ground" }
        { id: "b11", x: 8, y: -2, width: 1.6, height: 7.1, type: "ground" }
      ]
        @label "Platforms"
        @description "Canonical terrain — seeds the body authority's collision AND the canvas bars via RIYA_LEVEL_DATA. Bars sample y = x/8 + 4."
        @tier "domain"
      stars : [RiyaDerivPickup] = [
