        @tier "presentation"
      height : number = 480
        @label "Canvas Height"
        @description "math-canvas display height in px."
        @tier "presentation"
    }
  }

  trait DerivChallenge -> @rebindable RiyaDerivState [game-core, instance] {
    initial: idle

    state idle {
      DERIV_PICKED -> idle when (and (== @entity.zoneId @config.zoneId) (== @entity.active true))
        (if (== @payload.kind "tangent")
          (do
            (emit DERIV_BURST { particles: (array/concat
              { id: "narrative-tangent", type: "narrative", x: @payload.x, z: (+ @payload.y 1.5), y: 0, message: "dy/dx = x/8", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#f472b6", size: 0.7, vx: 0, vy: 0, vz: 0, particleCount: 1 }
              []) }))
          null)
    }

    emits {
      DERIV_BURST -> external {
        particles : [RiyaDerivFx]
      }
        @description "Particle batch spawned on the tangent pickup's narrative beat; fx-particles fades it."
        @tier "domain"
    }

    listens {
      DERIV_PICKED { id : string!, kind : string!, x : number!, y : number!, glyph : string, message : string }
    }

    config {
      zoneId : string = "deriv"
        @label "Zone Id"
        @description "The zone this challenge choreography belongs to. Guards compare it against @entity.zoneId, so a composed open world fires it only while riya stands in this zone; standalone the entity default equals this knob and the guard is always true."
        @tier "domain"
    }
  }

  trait RiyaDerivClear -> @rebindable RiyaDerivState [interaction, instance] {
    initial: watching

    state watching {
      INIT -> watching
        (render-ui overlay null)

      RIYA_LEVEL_SOLVED -> watching
        (render-ui overlay {
          type: game-menu
          title: @config.clearTitle
          subtitle: @config.clearSubtitle
          options: [ { id: "next", label: "Next ▶", event: "DERIV_NEXT", variant: "primary" } ]
        })

      DERIV_NEXT -> watching
        (render-ui overlay null)
        (navigate @config.nextPath)

      CLOSE -> watching
        (render-ui overlay null)
    }

    listens {
      RIYA_LEVEL_SOLVED { level : string }
      DERIV_NEXT { id : string }
      CLOSE
    }

    config {
      nextPath : string = "/riya-deriv"
        @label "Next Path"
        @description "Page the clear overlay's Next button navigates to. Standalone default replays this world; riya-game-platformer overrides it with the next world's path."
        @tier "presentation"
      clearTitle : string = "Derivative clear ★"
        @label "Clear Title"
        @description "Overlay title once every star is collected."
        @tier "presentation"
      clearSubtitle : string = "You skated the slope of world 3's valley — low where the valley is flat, high where it is steep."
        @label "Clear Subtitle"
        @description "One-line celebration under the clear title."
        @tier "presentation"
    }
  }

  page "/riya-deriv" as RiyaDerivPage -> DerivLevelData, DerivBody, DerivGate, DerivFx, DerivPickup, DerivTutorial, RiyaDerivGenre, RiyaDerivPlay, DerivChallenge, RiyaDerivClear
}
